    for p in (SITE / "validation").rglob("*"):
        if p.is_file():
            text = p.read_text(encoding="utf-8")
            if p.suffix == ".json":
                text = "\n".join(_strings(json.loads(text)))
            for pat in bans:
                m = pat.search(text)
                assert not m, (p.name, m and m.group())

